PRAGMA foreign_keys = ON;
CREATE TABLE customers (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE products (id TEXT PRIMARY KEY, name TEXT NOT NULL, episode_id TEXT NOT NULL, price_cents INTEGER NOT NULL CHECK(price_cents>=0), currency TEXT NOT NULL DEFAULT 'EUR', content_ready INTEGER NOT NULL DEFAULT 0 CHECK(content_ready IN(0,1)));
CREATE TABLE orders (id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customers(id), external_reference TEXT UNIQUE, status TEXT NOT NULL CHECK(status IN('pending','paid','refunded','cancelled')), total_cents INTEGER NOT NULL CHECK(total_cents>=0), currency TEXT NOT NULL, created_at INTEGER NOT NULL, paid_at INTEGER);
CREATE TABLE order_items (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), product_id TEXT NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL DEFAULT 1 CHECK(quantity>0), unit_price_cents INTEGER NOT NULL CHECK(unit_price_cents>=0));
CREATE TABLE entitlements (id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customers(id), order_item_id TEXT NOT NULL REFERENCES order_items(id), product_id TEXT NOT NULL REFERENCES products(id), unit_index INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'valid' CHECK(status IN('valid','revoked')), granted_at INTEGER NOT NULL, expires_at INTEGER, activated_at INTEGER, first_completed_at INTEGER, replay_until INTEGER, UNIQUE(order_item_id,unit_index));
CREATE TABLE portal_sessions (id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customers(id), entitlement_id TEXT NOT NULL REFERENCES entitlements(id), client_key TEXT NOT NULL, started_at INTEGER NOT NULL, last_at INTEGER NOT NULL, before_activation INTEGER NOT NULL CHECK(before_activation IN(0,1)));
CREATE TABLE checklist_progress (entitlement_id TEXT NOT NULL REFERENCES entitlements(id), step_key TEXT NOT NULL, completed INTEGER NOT NULL CHECK(completed IN(0,1)), updated_at INTEGER NOT NULL, PRIMARY KEY(entitlement_id,step_key));
CREATE TABLE game_runs (id TEXT PRIMARY KEY, entitlement_id TEXT NOT NULL REFERENCES entitlements(id), run_number INTEGER NOT NULL CHECK(run_number>0), activation_key TEXT NOT NULL UNIQUE, device_token_hash TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('active','completed','expired')), current_stage INTEGER NOT NULL DEFAULT 1 CHECK(current_stage BETWEEN 1 AND 8), started_at INTEGER NOT NULL, last_at INTEGER NOT NULL, completed_at INTEGER, UNIQUE(entitlement_id,run_number));
CREATE UNIQUE INDEX one_active_run_per_entitlement ON game_runs(entitlement_id) WHERE status='active';
CREATE TABLE game_stage_progress (run_id TEXT NOT NULL REFERENCES game_runs(id), stage INTEGER NOT NULL CHECK(stage BETWEEN 1 AND 7), first_opened_at INTEGER NOT NULL, last_opened_at INTEGER NOT NULL, completed_at INTEGER, attempts INTEGER NOT NULL DEFAULT 0, wrong_attempts INTEGER NOT NULL DEFAULT 0, hints INTEGER NOT NULL DEFAULT 0, active_ms INTEGER NOT NULL DEFAULT 0 CHECK(active_ms>=0), last_heartbeat_at INTEGER, PRIMARY KEY(run_id,stage));
CREATE TABLE game_events (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES game_runs(id), stage INTEGER CHECK(stage BETWEEN 1 AND 7), type TEXT NOT NULL, occurred_at INTEGER NOT NULL, request_hash TEXT NOT NULL, metadata TEXT NOT NULL DEFAULT '{}');
CREATE TABLE email_preferences (customer_id TEXT PRIMARY KEY REFERENCES customers(id), marketing_opt_in INTEGER NOT NULL DEFAULT 0 CHECK(marketing_opt_in IN(0,1)), consent_at INTEGER, unsubscribed_at INTEGER);
CREATE TABLE email_events (id TEXT PRIMARY KEY, customer_id TEXT REFERENCES customers(id), template_key TEXT NOT NULL, category TEXT NOT NULL CHECK(category IN('transactional','marketing')), status TEXT NOT NULL CHECK(status IN('draft','blocked','queued','sent','failed')), created_at INTEGER NOT NULL, sent_at INTEGER, provider_reference TEXT UNIQUE);
CREATE TABLE audit_events (id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, entity_id TEXT, created_at INTEGER NOT NULL);
CREATE INDEX orders_customer_date ON orders(customer_id,created_at);
CREATE INDEX orders_date_status ON orders(created_at,status);
CREATE INDEX items_product ON order_items(product_id,order_id);
CREATE INDEX entitlements_customer ON entitlements(customer_id,status);
CREATE INDEX entitlements_product ON entitlements(product_id,granted_at);
CREATE INDEX portal_customer_time ON portal_sessions(customer_id,started_at);
CREATE INDEX portal_client_time ON portal_sessions(entitlement_id,client_key,last_at);
CREATE INDEX checklist_done ON checklist_progress(entitlement_id,completed);
CREATE INDEX runs_entitlement_time ON game_runs(entitlement_id,started_at);
CREATE INDEX runs_activity ON game_runs(status,last_at);
CREATE INDEX stages_stage ON game_stage_progress(stage,completed_at);
CREATE INDEX events_run_time ON game_events(run_id,occurred_at);
CREATE INDEX email_customer_time ON email_events(customer_id,created_at);
